import {socketDiagram} from './socket-ui.js';
import {ACTIVE_GEMS,SUPPORT_GEMS,compileSkill,compatible} from './gems.js';
import {CURRENCIES,SOCKET_COLORS,weaponFor,gemSocket,colorFits,EQUIPMENT_SLOTS,SLOT_NAMES,gearType,gearLabel,equipmentStats} from './progression.js';
const socket=(color,text='',locked=false)=>`<span class="socket ${locked?'unlinked':''}" style="--socket:${SOCKET_COLORS[color]?.hex||'#526148'}" title="${SOCKET_COLORS[color]?.name||'未開啟'}孔">${text||color||'×'}</span>`;
export function wallet(g){return `<div class="wallet">${Object.entries(CURRENCIES).map(([id,c])=>`<span><img src="assets/${id}.svg" alt="">${c.name}<b>${g.bag.currency[id]}</b></span>`).join('')}</div>`}
export function buildPanel(game,modal,close){
 let craftId=game.equipped.find(Boolean)||game.bag.weapons[0].id;
 function render(message=''){
 const scroll=document.querySelector('.build-panel')?.scrollTop||0;
 modal(`<div class="build-panel"><div class="build-heading"><div><span class="eyebrow">INVENTORY / 第 ${game.round}/3 回合 · 第 ${game.wave}/15 波</span><h2>${game.forgeUnlocked?'匠魂工坊':'行囊與裝備'}</h2></div><button id="closeBuild" class="secondary">完成配置 ↗</button></div>${wallet(game)}<div class="socket-legend"><span><i class="legend-chain">∞</i> 金鏈：與主動孔相連</span><span><i>×</i> 斷鏈：輔助不生效</span><span><i>＋</i> 未開孔：先用匠魂石</span></div><p class="build-intro">只有戰利品中的寶石能裝備。主動技能放在首孔，輔助寶石必須同色、相容且與首孔相連；白孔接受所有顏色。</p><div class="build-notice" role="status">${message||'升級可三選一寶石；小怪 3%、Boss 80% 機率掉落裝備並自動收納。每 5 波 Boss 後可改造所有裝備孔洞。'}</div><div class="link-grid">${game.links.map((row,i)=>{
 const w=weaponFor(game,i),a=ACTIVE_GEMS[row.active],stats=compileSkill(row,game.player,game.gemLevels,w);
 return `<section class="link-card" style="--gem-color:${a?.color||'#b6a274'}"><div class="link-number">${SLOT_NAMES[i]}<span>${w?`${w.sockets.length} 孔 · ${w.linked} 孔串連`:'尚未取得裝備'}</span></div><label class="equipment-label">裝備<select data-weapon="${i}">${w?'':'<option value="">尚無裝備</option>'}${game.bag.weapons.filter(v=>gearType(v)===EQUIPMENT_SLOTS[i]).map(v=>`<option value="${v.id}" ${w?.id===v.id?'selected':''} ${game.equipped.some((id,k)=>k!==i&&id===v.id)?'disabled':''}>${gearLabel(v)}</option>`).join('')}</select></label>${w?`<p class="gear-bonus">${gearLabel(w)} · ${w.rarity==='epic'?'史詩':w.rarity==='rare'?'稀有':'普通'} · 對應標籤傷害 +${w.power}%</p>${socketDiagram(w,row)}<label class="equipment-label">主動技能<select data-active="${i}"><option value="">空插槽</option>${game.bag.active.map(id=>`<option value="${id}" ${row.active===id?'selected':''} ${!colorFits(w.sockets[0],id)||game.links.some((r,k)=>k!==i&&r.active===id)?'disabled':''}>${ACTIVE_GEMS[id].name} · ${SOCKET_COLORS[gemSocket(id)].name}${!colorFits(w.sockets[0],id)?'（孔色不符）':''}</option>`).join('')}</select></label><p class="active-description">${a?.desc||'從已取得的技能中選擇；裝入主動寶石後，此裝備會獨立自動施放。'}</p><div class="support-links">${row.supports.map((id,j)=>{
 const available=j+1<w.sockets.length&&j+1<w.linked&&a;
 return `<div class="support-socket ${available?'support-connected':'support-disabled'}">${socket(w.sockets[j+1],id?SUPPORT_GEMS[id].icon:'',!available)}<div><label>輔助 ${j+1}${j+1>=w.sockets.length?' · 未開孔':j+1>=w.linked?' · 未連結':id?' · 已連結／生效':' · 已連結／空孔'}</label><select data-row="${i}" data-socket="${j}" ${available?'':'disabled'}><option value="">空插槽</option>${game.bag.support.map(sid=>`<option value="${sid}" ${sid===id?'selected':''} ${!compatible(row.active,sid)||!colorFits(w.sockets[j+1],sid)||game.links.some((r,k)=>r.supports.some((v,l)=>v===sid&&(k!==i||l!==j)))?'disabled':''}>${SUPPORT_GEMS[sid].name} · ${SOCKET_COLORS[gemSocket(sid)].name}</option>`).join('')}</select><small>${id?SUPPORT_GEMS[id].desc:'升級或 Boss 獎勵可取得輔助寶石。'}</small></div></div>`}).join('')}</div>${stats?`<div class="link-stats"><div><strong>${Math.round(stats.damage)}</strong><span>單次命中</span></div><div><strong>${stats.rate.toFixed(2)}/s</strong><span>施放頻率</span></div></div>`:''}`:'<p class="active-description">擊殺敵人取得對應裝備後，可在此串連一顆主動與最多三顆輔助寶石。</p>'}</section>`}).join('')}</div>
 ${game.forgeUnlocked?`<section class="forge-section"><span class="eyebrow">BOSS CLEARED / FORGE</span><h2>重塑你的裝備</h2><p>增孔與連孔必定成功；隨機改色消耗較少，指定改色需要兩顆幻彩石。改色不會摧毀寶石，不合色者會退回背包。</p><label class="equipment-label">製作目標<select id="forgeWeapon">${game.bag.weapons.map(w=>`<option value="${w.id}" ${w.id===craftId?'selected':''}>${w.name}</option>`).join('')}</select></label>${socketDiagram(game.bag.weapons.find(w=>w.id===craftId),game.links[game.equipped.indexOf(craftId)])}<div class="craft-actions"><button class="secondary" data-craft="socket">增開一孔 · 匠魂石 ×2</button><button class="secondary" data-craft="link">串連下一孔 · 連結石 ×2</button><button class="secondary" data-craft="reroll">全部隨機改色 · 幻彩石 ×1</button></div><div class="target-color"><label>孔位<select id="colorIndex">${game.bag.weapons.find(w=>w.id===craftId).sockets.map((_,i)=>`<option value="${i}">第 ${i+1} 孔</option>`).join('')}</select></label><label>指定顏色<select id="colorValue"><option value="R">紅色</option><option value="G">綠色</option><option value="B">藍色</option></select></label><button class="primary" id="recolor">指定改色 · 幻彩石 ×2</button></div></section>`:'<div class="forge-locked">◇ 工坊尚未開放 · 再擊敗 '+(5-(game.wave-1)%5)+' 波即可製作孔洞</div>'}
 <div class="gear-summary">裝備加成：護甲 +${equipmentStats(game).armor} · 移速 +${equipmentStats(game).speed}%<br>最近自動拾取：${game.lootHistory.map(w=>w.name).join('、')||'尚無掉落'}<br>行囊上限 40 件；滿額時最舊的未裝備物品會轉為 2 顆匠魂石。</div><details class="build-codex"><summary>寶石收藏 · 主動 ${game.bag.active.length}/18 · 輔助 ${game.bag.support.length}/18</summary><div class="codex-grid">${[...game.bag.active.map(id=>ACTIVE_GEMS[id]),...game.bag.support.map(id=>SUPPORT_GEMS[id])].map(a=>`<div><strong>${a.icon} ${a.name}</strong><p>${a.desc}</p></div>`).join('')}</div></details><p class="build-footnote">每局重新開始時，武器、技能與通貨全部重置。僅保留一把朽木杖與烈焰火球。</p></div>`);
 document.querySelector('.build-panel').scrollTop=scroll;document.getElementById('closeBuild').onclick=close;
 document.querySelectorAll('[data-active]').forEach(el=>el.onchange=()=>{const r=game.configure(+el.dataset.active,'active',0,el.value||null);render(r.ok?'技能已更新。':r.reason)});
 document.querySelectorAll('[data-socket]').forEach(el=>el.onchange=()=>{const r=game.configure(+el.dataset.row,'support',+el.dataset.socket,el.value||null);render(r.ok?'輔助寶石已更新。':r.reason)});
 document.querySelectorAll('[data-weapon]').forEach(el=>el.onchange=()=>{if(!el.value)return;const r=game.equip(+el.dataset.weapon,el.value);render(r.ok?'裝備已更換；不合色寶石已退回行囊。':r.reason)});
 if(game.forgeUnlocked){document.getElementById('forgeWeapon').onchange=e=>{craftId=e.target.value;render()};document.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>{const r=game.craft(craftId,b.dataset.craft);render(r.ok?`製作完成：${game.bag.weapons.find(w=>w.id===craftId).sockets.length} 孔已開啟，${game.bag.weapons.find(w=>w.id===craftId).linked} 孔串連。`:r.reason)});document.getElementById('recolor').onclick=()=>{const r=game.craft(craftId,'recolor',{index:+document.getElementById('colorIndex').value,color:document.getElementById('colorValue').value});render(r.reason)}}
 }render();
}
